"Puede haber más: antes de salir, fijate acá.": "可能还有其他情况：出门前在这里查看。",
"Hoy no tenemos avisos cargados. Antes de salir, fijate acá si hay algo.": "今天没有提示。出门前请在这里查看是否有情况。",
