"Paros, marchas y cortes en las noticias del día.": "今日新闻中的罢工、游行和封路信息。",
"Estado de U-Bahn, tranvía y colectivos": "U-Bahn、有轨电车和公交运行状态",
"Demoras, obras y servicios de reemplazo, en vivo (BVG). En alemán.": "延误、施工和替代服务实时信息(BVG)。德语。",
"Estado del S-Bahn": "S-Bahn运行状态",
"Cambios por obras y problemas del día. En alemán.": "施工变更和当日故障。德语。",
"Huelgas (Streik) y manifestaciones (Demo) en las noticias del día.": "今日新闻中的罢工(Streik)和示威(Demo)。",
"Av. del Libertador cortada en Palermo": "巴勒莫的解放者大道封闭",
"Por el desarme de los escenarios de la visita del Papa, hay cortes en Av. del Libertador entre Av. Olleros y Ugarteche. Si pasás por la zona, calculá más tiempo o usá el subte.": "由于教皇访问的舞台正在拆除，解放者大道在奥列罗斯大道和乌加尔特切街之间封闭。经过该区域请预留更多时间或乘坐地铁。",
"Consulados y embajadas": "领事馆和大使馆",
"¿Tu país no está en la lista?": "你的国家不在列表中？",
"Buscá su consulado o embajada en el mapa.": "在地图上查找其领事馆或大使馆。",
"Ayuda: emergencias, policía, consulados": "求助：紧急情况、警察、领事馆",
"Consulado General": "总领事馆",
"Embajada": "大使馆",
"Embajada y sección consular": "大使馆及领事处",
"Pasaportes, documentos y ayuda a sus ciudadanos.": "为本国公民办理护照、证件并提供帮助。",
"Pasaportes, documentos y ayuda a sus ciudadanos. Tiene teléfono de emergencias en su web.": "为本国公民办理护照、证件并提供帮助。官网上有紧急电话。",
"Ayuda a sus ciudadanos: pasaportes y documentos.": "为本国公民提供帮助：护照和证件。",
"Ayuda a sus ciudadanos: pasaportes y documentos. Queda lejos del centro: llegá en taxi o app.": "为本国公民提供帮助：护照和证件。离市中心较远，建议打车前往。",
"Policía de la Ciudad. Para denuncias; en una emergencia llamá al 911.": "市警察。可在此报案；紧急情况请拨打911。",
