"Bar notable frente al viejo Mercado de Hacienda, punto de reunión de reseros y vecinos.": "旧牲畜市场对面的历史酒吧，赶牛人和街坊的聚会点。",
"Un viejo almacén con despacho de bebidas de 1915, con jamones colgados y estanterías hasta el techo.": "1915 年的老杂货铺兼酒吧，挂着火腿，货架一直顶到天花板。",
"Bar notable de 1893 con noches de tango y milonga de barrio.": "1893 年的历史酒吧，有探戈之夜和街区米隆加。",
"Tanguería histórica en una esquina colonial, con orquesta en vivo y pocos lugares.": "殖民时期街角的历史探戈屋，有现场乐队，座位不多。",
"Un bar chiquito donde el tango se toca y se baila a un metro de tu mesa.": "一家小酒吧，离你的桌子一米远就有人演奏和跳探戈。",
"Cena show en un conventillo reciclado, con tango y folclore.": "在改建的公寓大院里的晚宴秀，有探戈和民谣。",
"Gran show de tango en un antiguo cine, al lado del Obelisco.": "方尖碑旁旧电影院里的大型探戈表演。",
"Cena show en el Abasto, donde paraba Gardel.": "阿巴斯托的晚宴秀，加德尔当年常来这里。",
"Una milonga tradicional y chica, de las más respetadas por los bailarines.": "一家小型传统米隆加，深受舞者推崇。",
