"Club de jazz con mesas, buena acústica y shows casi todas las noches.": "有座位、音响好的爵士俱乐部，几乎每晚都有演出。",
"Disquería, bar y sala de jazz con jardín al fondo.": "唱片店、酒吧兼爵士演出场地，后面有花园。",
"Sala clásica de recitales medianos: rock, tango, folclore y humor.": "经典的中型演出场馆：摇滚、探戈、民谣和喜剧。",
"Un viejo cine convertido en sala de rock.": "老电影院改成的摇滚演出场地。",
"Una fábrica de aceite reciclada con recitales, teatro y fiestas en el patio.": "旧榨油厂改建，庭院里有演唱会、戏剧和派对。",
"Un bar mínimo de 1893 donde se canta tango bien entrada la noche.": "1893 年的小酒吧，探戈一直唱到深夜。",
"Uno de los primeros bares a puertas cerradas de la ciudad; coctelería seria.": "城里最早的私密酒吧之一；鸡尾酒很讲究。",
"Coctelería inspirada en las novelas de Julio Verne.": "以儒勒·凡尔纳小说为灵感的鸡尾酒。",
"Bar especializado en martinis y cócteles clásicos.": "专做马提尼和经典鸡尾酒的酒吧。",
"Bar en una mansión de principios del siglo XX, con escalera de mármol y jardín.": "开在 20 世纪初宅邸里的酒吧，有大理石楼梯和花园。",
"Pub inglés con pool al fondo, curry y cerveza tirada.": "英式酒吧，后面有桌球，供应咖喱和生啤。",
"Hotel art déco a una cuadra de Plaza de Mayo, con pileta en la terraza.": "离五月广场一个街区的装饰艺术风格酒店，屋顶有泳池。",
