"Hotel histórico de 1910 a una cuadra del Congreso.": "离国会一个街区的 1910 年历史酒店。",
"Edificio histórico de estilo neocolonial español en el Bajo.": "Bajo 区一座西班牙新殖民风格的历史建筑。",
"Torre frente a la Torre Monumental y la estación Retiro, con pileta y canchas.": "面对英国钟楼和雷蒂罗车站的高楼，有泳池和球场。",
