"Torre moderna de la familia del Alvear, con pileta en altura.": "阿尔韦亚尔家族的现代高楼，泳池在高层。",
"Hotel de lujo en una de las cuadras más elegantes, cerca de Patio Bullrich.": "位于最优雅街区之一的豪华酒店，靠近 Patio Bullrich 商场。",
"Hotel moderno a pocas cuadras del Cementerio de la Recoleta.": "离雷科莱塔墓园几个街区的现代酒店。",
"Pocas habitaciones en el edificio de un club centenario, con restaurante francés.": "百年俱乐部大楼里的少量客房，有法式餐厅。",
"Hotel boutique de lujo con servicio muy personalizado.": "服务非常贴心的豪华精品酒店。",
"Una de las torres más altas de la ciudad, con bar y pileta en los últimos pisos.": "城里最高的大楼之一，顶层有酒吧和泳池。",
"La casa donde se alojaba Francis Ford Coppola, con un jardín tropical y pocas suites.": "弗朗西斯·福特·科波拉曾住过的房子，有热带花园和少量套房。",
"Un antiguo convento convertido en hotel boutique, a media cuadra de la Plaza Serrano.": "旧修道院改成的精品酒店，离塞拉诺广场半个街区。",
"Casona reciclada con terraza, cerca de Plaza Italia y del subte.": "改建的宅邸，有屋顶露台，靠近意大利广场和地铁。",
"El gran teatro público de la ciudad: tres salas, cine, fotogalería y entradas accesibles.": "城市的大型公立剧院：三个舞台、一个电影院、一个摄影展厅，票价实惠。",
