"Sala art déco de 1936 con un cielo estrellado en el techo.": "1936 年的装饰艺术风格剧场，天花板上是星空。",
"Un pasaje a cielo abierto con varias salas de teatro, bares y stand up.": "一条露天通道，有好几家剧院、酒吧和单口喜剧。",
"Cine de la universidad con ciclos, clásicos y estrenos independientes.": "大学电影院，有影展、经典电影和独立新片。",
"La cinemateca del Teatro San Martín: ciclos de autor y retrospectivas.": "圣马丁剧院的电影资料馆：艺术片影展和回顾展。",
"Muestras, teatro, música y cine a precios bajos, detrás del Teatro San Martín.": "圣马丁剧院后面，价格低廉的展览、戏剧、音乐和电影。",
"Muestras de arte y espectáculos arriba de Galerías Pacífico.": "太平洋拱廊商场楼上的艺术展览和演出。",
"Teatro público donado por Quinquela Martín, con sus murales en el hall.": "金克拉·马丁捐赠的公立剧院，门厅里有他的壁画。",
