"Un parque grande sobre el río con juegos, arena y sombrillas en verano.": "河边的大公园，有游乐场、沙滩，夏天有遮阳伞。",
"El Nuevo Gasómetro, la cancha de San Lorenzo, uno de los cinco grandes.": "新煤气罐球场，五大俱乐部之一圣洛伦索的主场。",
"La cancha de Ferro Carril Oeste, con tribunas de madera centenarias.": "西部铁路队的球场，有百年历史的木制看台。",
"La cancha del Torito de Mataderos, verde y negra como todo el barrio.": "马塔德罗斯“小公牛”队的球场，和整个街区一样是绿黑配色。",
"Un mercado enorme junto al río: mimbre, muebles, plantas, decoración y puestos de comida.": "河边的巨大市场：藤编、家具、植物、家居用品和美食摊位。",
