"La mansión de Victoria Ocampo, donde se alojaron Borges, Tagore y Camus. Hoy es de la UNESCO.": "维多利亚·奥坎波的宅邸，博尔赫斯、泰戈尔和加缪都曾在此留宿。如今属于联合国教科文组织。",
"Un pueblo uruguayo tranquilo con playas de río, bodegas y viñedos, al que se llega cruzando el Delta.": "穿过三角洲就能到达的宁静乌拉圭小镇，有河滩、酒庄和葡萄园。",
