"Salidas a caballo de una hora o de día entero, aptas para quien nunca montó.": "一小时到一整天的骑马活动，没骑过马的人也可以。",
"Escuelas con lancha o cable que dan clases para principiantes.": "有船或缆索的学校，提供初学者课程。",
"Un sobrevuelo corto por el río, Puerto Madero, el Obelisco y los estadios.": "短途飞行，飞越河流、马德罗港、方尖碑和体育场。",
