"Una vieja estación de tren rodeada de restaurantes de campo y feria de artesanos.": "旧火车站，周围是乡村餐厅和手工艺品集市。",
"Un castillo de estilo francés en medio del campo, con parque diseñado por Carlos Thays.": "乡村中的法式城堡，公园由卡洛斯·塔伊斯设计。",
