"Parrilla de barrio con las paredes escritas por los clientes.": "墙上写满客人留言的街区烤肉店。",
"Parrilla tradicional frente al Parque Lezama, muy de vecinos.": "莱萨马公园对面的传统烤肉店，非常本地。",
