"Tacos y cocina mexicana casera.": "塔可和家常墨西哥菜。",
"Un patio grande lleno de plantas con bar y restaurante.": "满是植物的大庭院，有酒吧和餐厅。",
"Cervecería con decenas de canillas de cerveza artesanal y patio.": "有几十个精酿啤酒酒头和庭院的啤酒吧。",
"Café notable de 1887, a dos cuadras de Plaza de Mayo.": "1887 年的历史咖啡馆，离五月广场两个街区。",
