"Trattoria italiana tradicional del centro.": "市中心的传统意式小餐馆。",
"Asador criollo a la vista sobre la peatonal Lavalle, con décadas recibiendo turistas.": "拉瓦列步行街上，明火烤全羊就在眼前，几十年来接待游客。",
"Uno de los restaurantes coreanos más antiguos de la ciudad, en Once.": "城里最古老的韩国餐厅之一，在昂塞。",
"Parrilla sencilla y muy pedida por su precio, cerca de la avenida 9 de Julio.": "7 月 9 日大道附近一家简单的烤肉店，因价格实惠很受欢迎。",
"Parrilla y cocina española a una cuadra de la calle Florida.": "离佛罗里达街一个街区，有烤肉和西班牙菜。",
"Un bistró chiquito y colorido con barra y platos de autor.": "小巧多彩的小酒馆，有吧台和创意菜。",
"Pizzas finas y cocina italiana en un salón con arte.": "满是艺术品的餐厅里的薄底披萨和意大利菜。",
