"Pedí paella o puchero para compartir.": "点西班牙海鲜饭或炖肉锅（puchero）分享。",
"Un plato suele alcanzar para dos.": "一道菜通常够两个人吃。",
"Ideal para un almuerzo largo de invierno.": "适合冬天慢慢吃一顿长午餐。",
"Clásico para antes o después del teatro.": "看戏前后的经典去处。",
"Muy elegido para comer después del teatro.": "看完戏后吃饭的热门选择。",
"Se come de parado en la barra, como manda la tradición.": "按照传统，站在柜台前吃。",
"Pizza a la piedra, más fina que la de sus vecinas.": "石窑烤披萨，比邻居家的更薄。",
"Perfecto para una tarde fría.": "最适合寒冷的下午。",
"A una cuadra de Plaza de Mayo.": "离五月广场一个街区。",
"Bajá a ver las mesas aunque no juegues.": "就算不打球，也下楼去看看台球桌。",
"Una opción sincera en una zona cara.": "在昂贵地段里的实在选择。",
"Reservá para la noche.": "晚上请预订。",
"Es chico: conviene reservar.": "店很小：最好预订。",
"Sentate afuera un domingo para ver bailar tango.": "周日坐在外面看人跳探戈。",
"Pedí una picada para compartir.": "点一份拼盘分享。",
"Buen descanso después del Museo Histórico Nacional.": "参观国家历史博物馆后休息一下的好地方。",
"Probá el sándwich de crudo y queso.": "试试生火腿奶酪三明治。",
"Reservá los fines de semana.": "周末请预订。",
"Bueno y barato para seguir caminando.": "好吃又便宜，吃完继续走。",
"El patio es un oasis en un día de feria.": "集市日里，庭院就是一片绿洲。",
"Almuerzo ideal para la visita a La Boca. Solo de día.": "参观博卡时吃午饭的理想去处。仅限白天。",
"Andá y volvé en taxi o app.": "往返乘出租车或打车。",
"Es cara. Pedí mesa en la terraza.": "价格较高。要一张露台上的桌子。",
