"El cordero al asador es la especialidad.": "招牌是烤全羊。",
"Se come de parado, con moscato.": "站着吃，配一杯莫斯卡托甜酒。",
"Compartí: un plato alcanza para dos o tres.": "分着吃：一道菜够两三个人。",
"Parada clásica antes de un recital en la zona.": "附近有演唱会前的经典去处。",
"Andá de noche a jugar al ping-pong con una cerveza.": "晚上去，边喝啤酒边打乒乓球。",
"Los fines de semana hay espera para el brunch.": "周末早午餐要等位。",
"Picada y vermut para el atardecer.": "日落时来份拼盘配味美思。",
"Pedí pastas caseras.": "点自制意面。",
"Bien de vecinos: sin vueltas y barata.": "当地人常去的店：朴实又便宜。",
"Los domingos al mediodía se llena de familias.": "周日中午满是一家人。",
"Los domingos combinalo con la feria de libros del parque.": "周日可以和公园里的书市一起逛。",
"Suele haber fila. Algunas cosas se agotan temprano.": "通常要排队。有些东西很早就卖完。",
"Combinalo con la Feria de Mataderos del domingo.": "可以和周日的马塔德罗斯集市一起安排。",
"Pedí picada con sidra tirada.": "点一份拼盘配生啤苹果酒。",
"Se puede ir solo al show, sin cena.": "可以只看表演，不吃晚餐。",
"Muy íntimo: reservá.": "非常私密：请预订。",
"Suelen ofrecer traslado desde el hotel.": "通常提供酒店接送。",
"Antes del show suelen dar una clase.": "表演前通常有一节舞蹈课。",
"A pasos de la Casa Museo Carlos Gardel.": "离卡洛斯·加德尔故居博物馆几步路。",
"Mirá los códigos: se invita a bailar con la mirada.": "注意规矩：邀请别人跳舞靠眼神。",
"Funciona los sábados a la noche. Reservá mesa.": "周六晚上举行。请预订桌位。",
"Los días cambian: confirmá antes de ir.": "日期不固定：出发前确认。",
"Comprá la entrada antes; algunas fechas se agotan.": "提前买票；有些日期会售罄。",
