"Mirá la agenda de la semana.": "查看本周节目单。",
"Subte B hasta Federico Lacroze.": "乘地铁 B 线到 Federico Lacroze 站。",
"Los lunes toca La Bomba de Tiempo.": "周一有 La Bomba de Tiempo 打击乐表演。",
"Arranca tarde. Entra poca gente.": "开始得很晚。能容纳的人不多。",
"No tiene cartel: tocá el timbre.": "没有招牌：按门铃。",
"Sentate en la barra.": "坐在吧台。",
"No sirven cerveza: es un bar para cócteles.": "不卖啤酒：这是鸡尾酒吧。",
"Andá temprano para sentarte en el jardín.": "早点去，才能坐到花园里。",
"Punto de encuentro de viajeros.": "旅行者的聚会点。",
"Buena base para recorrer el casco histórico a pie.": "步行探索历史中心的好落脚点。",
"La terraza mira a las cúpulas de la avenida.": "屋顶露台可以看到大道上的圆顶建筑。",
"A pasos del subte y de la calle Florida.": "离地铁和佛罗里达街几步路。",
"Pedí habitación con vista a la 9 de Julio.": "要一间能看到 7 月 9 日大道的房间。",
"Bien ubicado para ir al teatro caminando.": "位置方便，步行就能去剧院。",
"Cerca de Puerto Madero y del Palacio Libertad.": "靠近马德罗港和自由宫。",
"Las habitaciones altas tienen vista al río.": "高层房间可以看到河景。",
"Práctico si llegás o salís en tren o micro.": "乘火车或长途巴士到达或离开时很方便。",
"A pasos de la Plaza San Martín.": "离圣马丁广场几步路。",
"Buen punto para caminar Recoleta.": "步行游览雷科莱塔的好位置。",
"Tiene pileta y spa.": "有泳池和水疗。",
"Ambiente tranquilo y clásico.": "安静、古典的氛围。",
"Son pocas habitaciones: reservá con tiempo.": "房间很少：提前预订。",
"El bar de la terraza tiene vista de 360°.": "屋顶酒吧有 360° 景观。",
"En pleno Palermo Soho, pero silencioso.": "位于巴勒莫苏荷区中心，却很安静。",
"Tiene una pileta chica en la terraza.": "屋顶有一个小泳池。",
"Bien ubicado entre los parques y Palermo Soho.": "位于公园和巴勒莫苏荷区之间，位置很好。",
"Algunos días hay funciones a precio popular.": "有些日子演出有折扣价。",
"Mirá la cartelera de la semana.": "查看本周演出信息。",
"Recitales y musicales grandes.": "大型演唱会和音乐剧。",
"Buen lugar para decidir a último momento qué ver.": "适合临时决定看什么。",
"Entradas más baratas que en las cadenas.": "票价比连锁影院便宜。",
"La programación cambia cada semana.": "节目每周更换。",
