"Biergarten": "啤酒花园",
"Una cervecería o un biergarten": "一家啤酒馆或啤酒花园",
"De palacio en palacio": "宫殿巡游",
"2 palacios": "2座宫殿",
"Noche de club": "夜店之夜",
"Un club para bailar": "一家可以跳舞的夜店",
"Berlín en 1 día": "柏林一日游",
"La visita es gratis pero hay que anotarse antes en el sitio del Bundestag.": "参观免费，但需要提前在联邦议院网站上登记。",
"Caminala hasta la Isla de los Museos.": "沿着它一直走到博物馆岛。",
"El busto de Nefertiti. Cierra los lunes.": "奈费尔提蒂胸像。周一闭馆。",
"Reservá horario por internet.": "在网上预约时段。",
"Cena alemana en el bodegón más viejo de la ciudad.": "在城里最古老的酒馆吃德国菜晚餐。",
"Día 1 · Mañana": "第1天 · 上午",
"Anotate antes para la cúpula.": "提前登记参观穹顶。",
"Día 1 · Mediodía": "第1天 · 中午",
"Día 1 · Tarde": "第1天 · 下午",
"Elegí uno o dos museos: no da para todos.": "挑一两座博物馆：时间不够全看。",
"Día 1 · Noche": "第1天 · 晚上",
