"Temprano, con horario reservado.": "早点去，提前预约时段。",
"Está a dos cuadras.": "离这里两个街区。",
"Caminá por la orilla hasta el Louvre.": "沿河岸走到卢浮宫。",
"Elegí dos o tres salas.": "挑两三个展厅看。",
"Desde la Concordia hasta el Arco.": "从协和广场到凯旋门。",
