"O una cena en Montmartre.": "或在蒙马特吃晚餐。",
"Los pasajes cubiertos son para la lluvia.": "下雨天就逛廊街。",
"Chocolate caliente.": "热巧克力。",
"París gratis": "免费巴黎",
"La colección permanente es gratis.": "常设展免费。",
"Vista de la Torre Eiffel iluminada.": "看灯光下的埃菲尔铁塔。",
"Barquitos en la fuente.": "喷泉里的小帆船。",
