"El origen de París": "巴黎的发源地",
"La isla de la Cité, con Notre-Dame, la Sainte-Chapelle y la Conciergerie, y la tranquila isla Saint-Louis, unidas por puentes.": "西岱岛有圣母院、圣礼拜堂和古监狱，安静的圣路易岛与之以桥相连。",
"Hay muy pocos hoteles, pero todo lo demás queda a un paso.": "酒店很少，但其他一切都近在咫尺。",
"Barrio Chino y colina de pueblo": "中国城与村落般的山丘",
"El Barrio Chino entre torres modernas y, al lado, la Butte-aux-Cailles, con casas bajas, arte urbano y bares baratos.": "现代高楼之间的中国城，旁边是鹌鹑丘，有矮房子、街头艺术和便宜酒吧。",
"Económico y bien conectado, lejos del circuito turístico.": "价格实惠、交通便利，远离旅游路线。",
"Residencial y elegante": "高雅住宅区",
"El oeste tranquilo de la ciudad, con el Museo Marmottan Monet, calles comerciales de barrio y el bosque de Boulogne cerca.": "城市安静的西部，有马尔莫坦·莫奈美术馆、街区购物街，靠近布洛涅森林。",
"Muy seguro y silencioso, pero lejos de la vida nocturna.": "非常安全安静，但远离夜生活。",
"Verde y enorme": "绿意盎然、面积巨大",
"El gran bosque del oeste de París, con lagos, la Fundación Louis Vuitton y el Jardín de Aclimatación.": "巴黎西部的大森林，有湖泊、路易威登基金会和驯化园。",
"No es zona para alojarse: es para pasar el día.": "不适合住宿：适合来玩一天。",
"Moderno y al aire libre": "现代且户外",
"El gran parque del noreste, con la Ciudad de las Ciencias, la Philharmonie y canales para caminar.": "东北部的大公园，有科学城、爱乐音乐厅和可散步的运河。",
"Mejor para visitar que para alojarse.": "适合游览，不太适合住宿。",
