"Con la tarjeta, de a poco": "刷卡支付：正在逐步推广",
"Pagar apoyando la tarjeta sin contacto todavía no sirve en casi todo el metro: por ahora funciona en muchos buses, en el funicular de Montmartre y en la línea 14 desde el aeropuerto de Orly. Se va a ir sumando línea por línea en los próximos años.": "在地铁的大部分线路上还不能用非接触式银行卡直接刷卡乘车：目前可以在许多公交车、蒙马特缆车和从奥利机场出发的地铁 14 号线上使用。未来几年会逐条线路推广。",
